import { useState, type FormEvent } from 'react';
import { Button, Select, Stack, Switch, TextField } from '@jinx-ui/react';

export type ProfileSettings = {
  name: string;
  language: 'ru' | 'en';
  emailNotifications: boolean;
};

type ProfileSettingsFormProps = {
  onSave: (settings: ProfileSettings) => void;
};

const LANGUAGE_OPTIONS = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'English' },
];

export default function ProfileSettingsForm({ onSave }: ProfileSettingsFormProps) {
  const [settings, setSettings] = useState<ProfileSettings>({
    name: '',
    language: 'ru',
    emailNotifications: false,
  });

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave(settings);
  };

  return (
    <form onSubmit={handleSubmit}>
      <Stack direction="column" gap="var(--jx-space-4)">
        <TextField
          label="Имя"
          value={settings.name}
          onChange={(value: string) =>
            setSettings((current) => ({ ...current, name: value }))
          }
        />

        <Select
          label="Язык интерфейса"
          value={settings.language}
          options={LANGUAGE_OPTIONS}
          onChange={(value: string) =>
            setSettings((current) => ({
              ...current,
              language: value as ProfileSettings['language'],
            }))
          }
        />

        <Switch
          label="Уведомления на почту"
          checked={settings.emailNotifications}
          onChange={(checked: boolean) =>
            setSettings((current) => ({ ...current, emailNotifications: checked }))
          }
        />

        <Button type="submit" variant="primary">
          Сохранить
        </Button>
      </Stack>
    </form>
  );
}

